entries[53510] = { ["name"] = "Gefangener Frosch", ["text"] = "Questgegenstand\nBenutzen: Stimmt den gefangenen Frosch bei Vaniras Totem des Wachens auf ihre Sicht ab." }
entries[53637] = { ["name"] = "Sack Frösche", ["text"] = "Questgegenstand\nBenutzen: Werft einen von Vaniras abgestimmten Fröschen auf einen der erhellten Punkte auf den Echoinseln. Funktioniert nur, während Ihr auf einer Fledermaus reitet." }
entries[53641] = { ["name"] = "Eissplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Noch aus der letzten Eiszeit.\nMit Rechtsklick Euren eiskalten Frostling beschwören und freigeben." }
entries[54068] = { ["name"] = "Weißes Wollrhinozeros", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Reiten (150)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\nBeschwört ein reitbares weißes Wollrhinozeros oder gibt es frei. Dies ist ein sehr schnelles Reittier." }
entries[54069] = { ["name"] = "Flammender Hippogryph", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 60\nBenötigt Reiten (225)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren flammenden Hippogryph oder gibt ihn frei. Dieses Reittier passt sich Eurer Reitfertigkeit an." }
entries[54212] = { ["name"] = "Aufstellbares Statuenpodest", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Mit Rechtsklick werdet Ihr zu einer Heldenstatue von Euch selbst. (30 Min Abklingzeit)" }
entries[54215] = { ["name"] = "Vol'jins Kriegstrommeln", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schlagt Vol'jins Kriegstrommeln, um Trollbürger für die Rückeroberung der Echoinseln zu rekrutieren." }
